# 以下是自剧情开始时间以后，世界时局与经济系统的最高优先级即时演化状态，以及所有角色的最新动态。你在读取角色当前动态或调用当前时局/时代背景信息时必须以此最新的数据为准，以下信息的优先级高于其他任何背景设定：

<%_
function stripAddonForDisplay(data) {
  if (data == null || typeof data !== 'object' || Array.isArray(data)) return data;
  const HIDDEN = new Set(['平行演化', '刊报日期', '位面交汇']);
  function stripDeep(value) {
    if (value == null || typeof value !== 'object') return value;
    if (Array.isArray(value)) return value.map(stripDeep);
    const next = {};
    for (const [k, v] of Object.entries(value)) {
      if (HIDDEN.has(k)) continue;
      next[k] = stripDeep(v);
    }
    return next;
  }
  return stripDeep(_.cloneDeep(data));
}

/** 将 post_process_tags 扁平为 tag@attr=值 → 正文 */
function flattenPostProcessTags(raw) {
  const out = {};
  if (!raw || typeof raw !== 'object' || Array.isArray(raw)) return out;
  for (const [key, value] of Object.entries(raw)) {
    if (value == null) continue;
    if (typeof value === 'object' && !Array.isArray(value)) {
      const parts = String(key).split('_');
      if (parts.length >= 2) {
        const attrName = parts.pop();
        const tagName = parts.join('_');
        for (const [attrValue, block] of Object.entries(value)) {
          const text = String(block ?? '').trim();
          if (!text) continue;
          out[`${tagName}@${attrName}=${attrValue}`] = text;
        }
        continue;
      }
    }
    const text = String(value).trim();
    if (text) out[key] = text;
  }
  return out;
}

/** 若已是完整标签块则剥内文，否则原样返回 */
function tagInner(tagName, attrName, attrValue, stored) {
  const v = String(stored ?? '').trim();
  if (!v) return '';
  const openRe = new RegExp(
    `<\\s*${tagName}(?=[\\s/>])[^>]*\\b${attrName}\\s*=\\s*["']?${attrValue.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}["']?[^>]*>`,
    'i',
  );
  const closeRe = new RegExp(`</\\s*${tagName}\\s*>`, 'i');
  const openM = v.match(openRe);
  if (openM) {
    const start = openM.index + openM[0].length;
    const closeIdx = v.search(closeRe);
    if (closeIdx > start) return v.slice(start, closeIdx).trim();
  }
  return v;
}

function normalizeText(value) {
  return String(value ?? '')
    .replace(/\s+/g, ' ')
    .trim()
    .toLowerCase();
}

function splitKeywords(value) {
  return String(value ?? '')
    .split(/[、，,；;\n\r]+/g)
    .map(part => normalizeText(part))
    .filter(Boolean);
}

/** 活跃角色：顿号拆人名后，若含 · 分隔的西方名（可含中间名），整名与各段均可触发 */
function splitActiveCharacterKeywords(value) {
  const names = String(value ?? '')
    .split(/[、，,；;\n\r]+/g)
    .map(part => String(part ?? '').trim())
    .filter(Boolean);

  const keywords = [];
  for (const name of names) {
    const full = normalizeText(name);
    if (full) keywords.push(full);

    if (/[·・]/.test(name)) {
      for (const segment of name.split(/[·・]+/g)) {
        const part = normalizeText(segment);
        if (part) keywords.push(part);
      }
    }
  }
  return keywords;
}

function isUserMessage(msg) {
  return msg?.role === 'user' || msg?.is_user === true;
}

function isAssistantMessage(msg) {
  return msg?.role === 'assistant' || msg?.is_user === false;
}

function getRecentScanText(userLimit = 5, assistantLimit = 5) {
  try {
    const lastId = getLastMessageId();
    const messages = getChatMessages(`0-${lastId}`);
    const userTexts = [];
    const assistantTexts = [];

    for (let i = messages.length - 1; i >= 0; i--) {
      const msg = messages[i];
      if (!msg) continue;
      const text = String(msg.message ?? '').trim();
      if (!text) continue;

      if (isUserMessage(msg)) {
        if (userTexts.length < userLimit) userTexts.push(text);
      } else if (isAssistantMessage(msg)) {
        if (assistantTexts.length < assistantLimit) assistantTexts.push(text);
      }

      if (userTexts.length >= userLimit && assistantTexts.length >= assistantLimit) {
        break;
      }
    }

    return [...userTexts, ...assistantTexts].join('\n');
  } catch {
    /* ignore */
  }
  return '';
}

function collectCircleKeywords(circleName, entry) {
  return _.uniq([
    ...splitKeywords(circleName),
    ...splitActiveCharacterKeywords(entry?.活跃角色),
    ...splitKeywords(entry?.社群人脉),
  ]).filter(Boolean);
}

const pptFlat = flattenPostProcessTags(getvar('post_process_tags') || {});
const addonData = getvar('addon_data');
const worldMap = addonData && typeof addonData === 'object' ? addonData.世界 : null;
const isEmpty = !worldMap || Object.keys(worldMap || {}).length === 0;

let displayData = null;
if (!isEmpty) {
  const stripped = stripAddonForDisplay(worldMap);
  if (stripped != null && typeof stripped === 'object' && !Array.isArray(stripped)) {
    const out = {};
    for (const [name, world] of Object.entries(stripped)) {
      if (world && typeof world === 'object' && !Array.isArray(world) && world.降临 === true) {
        out[name] = world;
      }
    }
    displayData = out;
  }
}
const showWorld = !!(displayData && Object.keys(displayData).length > 0);

const worldSummaries = [];
if (displayData) {
  for (const name of Object.keys(displayData)) {
    const body = tagInner('世界状态摘要', 'world', name, pptFlat[`世界状态摘要@world=${name}`] || '');
    if (body) worldSummaries.push({ name, body });
  }
}

const socialRaw = addonData && typeof addonData === 'object' ? addonData.社交圈 : null;
const socialCircles = (socialRaw && typeof socialRaw === 'object' && !Array.isArray(socialRaw))
  ? _.cloneDeep(socialRaw)
  : {};
const scanText = normalizeText(getRecentScanText(5, 5));
const matched = {};
for (const [circleName, entry] of Object.entries(socialCircles)) {
  const keywords = collectCircleKeywords(circleName, entry);
  if (keywords.length === 0) continue;
  if (keywords.some(keyword => scanText.includes(keyword))) {
    matched[circleName] = entry;
  }
}
const showSocial = Object.keys(matched).length > 0;
_%>

<%_ for (const s of worldSummaries) { _%>
<世界状态摘要 world="<%= s.name %>">
<%- s.body %>
</世界状态摘要>
<%_ } _%>

<%_ if (showWorld) { _%>
<WorldPaper>
<%- YAML.stringify(displayData, { blockQuote: 'literal' }) %>
</WorldPaper>
<%_ } _%>

<%_ if (showSocial) { _%>
<社交圈>
<%- YAML.stringify(matched, { blockQuote: 'literal' }) %>
</社交圈>
<%_ } _%>

