function extractNpcBlocksByActs(totalXml, nameSet) {
  if (!nameSet || !nameSet.size) return [];
  const text = String(totalXml ?? '');
  const blocks = [];
  const seen = new Set();
  const re = /<\s*npc\b([^>]*)>([\s\S]*?)<\/\s*npc\s*>/gi;
  let m;
  while ((m = re.exec(text)) !== null) {
    const attrs = m[1] || '';
    const actM = attrs.match(/\bact\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s/>]+))/i);
    const act = actM ? String(actM[1] ?? actM[2] ?? actM[3] ?? '').trim() : '';
    if (!act || !nameSet.has(act) || seen.has(act)) continue;
    seen.add(act);
    blocks.push(m[0]);
  }
  return blocks;
}

/** 若 replica 为某团体核心人物，收集同团体其它核心人物姓名 */
function collectGroupPeerCoreNames(worldMap, replicaName) {
  const peers = [];
  if (!worldMap || typeof worldMap !== 'object' || Array.isArray(worldMap)) return peers;
  for (const world of Object.values(worldMap)) {
    if (!world || typeof world !== 'object' || Array.isArray(world)) continue;
    const groupDyn = world?.世界剧情态势?.团体动态 || world?.团体动态;
