    for (const scopeKey of ['世界背景团体', '当前区域团体']) {
      const scope = groupDyn[scopeKey];
      if (!scope || typeof scope !== 'object' || Array.isArray(scope)) continue;
      for (const group of Object.values(scope)) {
        if (!group || typeof group !== 'object') continue;
        const cores = group.核心人物;
        if (!cores || typeof cores !== 'object' || Array.isArray(cores)) continue;
        const coreNames = Object.keys(cores);
        const replicaInGroup = coreNames.some(n => personMatchesActiveRoles(n, replicaName));
        if (!replicaInGroup) continue;
        for (const n of coreNames) {
          if (!personMatchesActiveRoles(n, replicaName)) peers.push(n);
        }
      }
    }
  }
  return peers;
}

